function whereDoesItGo(tab: string): string {
  switch (tab) {
    case "Pay Bills":
      return "/paymentDashboard";
    case "Add Payee":
      return "/transferDashboard";
    default:
      return "(unknown)";
  }
}

for (const t of ["Pay Bills", "Add Payee", "Nonsense"]) {
  console.log(t.padEnd(12), "->", whereDoesItGo(t));
}

function noBreak(tab: string): string[] {
  const log: string[] = [];
  switch (tab) {
    case "a":
      log.push("did a");
      // no break - falls through
    case "b":
      log.push("did b");
      break;
    case "c":
      log.push("did c");
      break;
  }
  return log;
}

console.log('"a" ->', noBreak("a"));   // BOTH a and b
console.log('"b" ->', noBreak("b"));   // just b

function pickTab(tab: string): string {
  if (tab !== "Pay Bills") throw new Error(`unknown tab "${tab}"`);
  return "ok";
}

console.log(pickTab("Pay Bills"));

try {
  pickTab("Payy Bills");    // a typo
} catch (e) {
  console.log("caught:", (e as Error).message);
}

type TabName = "Pay Bills" | "Add Payee" | "Statements";

const valid: TabName[] = ["Pay Bills", "Add Payee", "Statements"];
console.log("the whole allowed set:", valid);

