import { writeProjectFile } from "../_shared/deno-helpers.ts";

// abstract + protected page. No test() call, so the runner ignores it.

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/zero/BasePage.ts", `// Week 6, Day 1 — the base every Zero Bank page shares.
//
// A second app, the same pattern. Compare with week5/generated/pages/BasePage.ts:
// the shape is identical, which is the point — a design pattern you can only apply
// to the app you learned it on is not a pattern.
import { type Page } from "@playwright/test";

export const ZERO_BASE = "http://zero.webappsecurity.com";

export abstract class BasePage {
  protected readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  /**
   * Zero Bank is HTTP-only: its HTTPS port offers a cipher suite modern Chromium
   * removed, so https:// fails with ERR_SSL_VERSION_OR_CIPHER_MISMATCH. The full
   * URL is built here so no page class or test has to remember that.
   */
  async goto(path: string): Promise<void> {
    await this.page.goto(\`\${ZERO_BASE}\${path}\`);
  }

  /** The page's own title — cheap way for a test to confirm where it landed. */
  async title(): Promise<string> {
    return this.page.title();
  }
}
`);

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/zero/HomePage.ts", `// Week 6, Day 1 — the Zero Bank landing page.
//
// Everything a person can do from this screen becomes one method named after the
// doing, not after the DOM.
import { type Locator, type Page } from "@playwright/test";
import { BasePage } from "./BasePage";

export class HomePage extends BasePage {
  readonly signInButton: Locator;
  readonly searchBox: Locator;
  readonly feedbackLink: Locator;
  readonly onlineBankingLink: Locator;

  constructor(page: Page) {
    super(page);
    this.signInButton = page.locator("#signin_button");
    this.searchBox = page.locator("#searchTerm");
    this.feedbackLink = page.locator("#feedback");
    this.onlineBankingLink = page.locator("#onlineBankingMenu");
  }

  async visit(): Promise<void> {
    await this.goto("/index.html");
  }

  async clickOnSignIn(): Promise<void> {
    await this.signInButton.click();
    await this.page.waitForURL(/login\\.html/);
  }

  async clickOnFeedbackLink(): Promise<void> {
    await this.feedbackLink.click();
    await this.page.waitForURL(/feedback\\.html/);
  }

  async clickOnOnlineBanking(): Promise<void> {
    await this.onlineBankingLink.click();
    await this.page.waitForURL(/online-banking\\.html/);
  }

  /**
   * There is no search button on this page, so the only way to submit is the
   * keyboard. waitForURL matters: the results page is a real navigation, and
   * without the wait the next line races it.
   */
  async searchFor(phrase: string): Promise<void> {
    await this.searchBox.fill(phrase);
    await this.page.keyboard.press("Enter");
    await this.page.waitForURL(/search\\.html/);
  }
}
`);

await writeProjectFile("week6/generated/zero/SearchResultsPage.ts", `// Week 6, Day 1 — the search results screen.
//
// One locator and no actions. A page class with a single field is still worth
// having: it is where the "results are <li><a>" fact lives, so no test learns it.
import { type Locator, type Page } from "@playwright/test";
import { BasePage } from "./BasePage";

export class SearchResultsPage extends BasePage {
  readonly resultLinks: Locator;

  constructor(page: Page) {
    super(page);
    // Verified against the live site: a search for "bank" yields exactly 2.
    this.resultLinks = page.locator("li a");
  }
}
`);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/day1-pom-structure.spec.ts", `// Week 6, Day 1 — the same pattern, a second app, plus a component.
//
// Written by a cell in week6/day1_2.ipynb. Run it yourself:
//   npx playwright test week6/generated/day1-pom-structure.spec.ts
import { test, expect } from "@playwright/test";
import { HomePage } from "./zero/HomePage";
import { SearchResultsPage } from "./zero/SearchResultsPage";
import { NavBar } from "./components/NavBar";
import { USERS } from "../../_shared/test-helpers";

test.describe("Zero Bank page objects", () => {
  test("Step 1 — the home page knows its own controls", async ({ page }) => {
    const homePage = new HomePage(page);
    await homePage.visit();

    await expect(homePage.signInButton).toBeVisible();
    await expect(homePage.searchBox).toBeVisible();
    await expect(homePage.feedbackLink).toBeVisible();
    expect(await homePage.title()).toContain("Zero");
  });

  test("Step 2 — searching, with no search button on the page", async ({ page }) => {
    const homePage = new HomePage(page);
    const results = new SearchResultsPage(page);

    await homePage.visit();
    await homePage.searchFor("bank");

    // Exactly 2, verified against the live site.
    await expect(results.resultLinks).toHaveCount(2);
  });

  test("Step 3 — one method per thing a person can do", async ({ page }) => {
    const homePage = new HomePage(page);

    await homePage.visit();
    await homePage.clickOnFeedbackLink();
    expect(page.url()).toContain("/feedback.html");

    await homePage.visit();
    await homePage.clickOnSignIn();
    expect(page.url()).toContain("/login.html");
  });

  test("Step 4 — goto() hides that this app is HTTP-only", async ({ page }) => {
    const homePage = new HomePage(page);
    await homePage.visit();

    // No test wrote "http://". BasePage owns that, so the day the site finally
    // fixes its TLS, one line changes.
    expect(page.url().startsWith("http://")).toBe(true);
  });
});

test.describe("The NavBar component", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/");
    await page.getByPlaceholder("Enter Email").fill(USERS[0].email);
    await page.getByPlaceholder("Enter Password").fill(USERS[0].password);
    await page.getByRole("button", { name: "Login" }).click();
    await page.waitForURL("**/dashboard");
  });

  test("Step 5 — one switch replaces twelve methods", async ({ page }) => {
    const navBar = new NavBar(page);
    await expect(navBar.tiles).toHaveCount(12);

    await navBar.clickOnTab("Pay Bills");
    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 6 — a different tab, the same method", async ({ page }) => {
    const navBar = new NavBar(page);

    await navBar.clickOnTab("Add Payee");
    await expect(page).toHaveURL(/transferDashboard/);
  });

  test("Step 7 — the ambiguous tab is resolved inside the component", async ({ page }) => {
    const navBar = new NavBar(page);

    // Two tiles say "Statements". The test does not have to know that.
    await expect(page.getByText("Statements", { exact: true })).toHaveCount(2);
    await navBar.clickOnTab("Statements");
  });

  test("Step 8 — an unknown tab throws instead of hanging", async ({ page }) => {
    const navBar = new NavBar(page);

    // Cast, because TypeScript would otherwise refuse this line outright — which
    // is the first line of defence. The throw is the second.
    const bad = navBar.clickOnTab("Nonexistent Tab" as never);
    await expect(bad).rejects.toThrow(/unknown tab/);
  });
});
`);

// Expected: 8 passed. Steps 1-4 are Zero Bank, 5-8 the component.
await runSpec("week6/generated/day1-pom-structure.spec.ts");

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// A component, not a page: a nav bar sits ON TOP of screens.

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/components/NavBar.ts", `// Week 6, Day 1 — a COMPONENT, not a page.
//
// The dashboard has twelve tiles. Writing clickOnPayBills(), clickOnAddPayee(),
// clickOnStatements() ... is twelve near-identical methods that all do one thing.
// One method plus a switch replaces them.
//
// It lives in components/ rather than pages/ because a nav bar is not a screen -
// it appears on top of screens. See day1_3 for when that distinction earns its keep.
import { type Locator, type Page } from "@playwright/test";

/** The tabs this dispatcher knows. A union type, so a typo is a compile error. */
export type TabName =
  | "Transaction History"
  | "Pay Bills"
  | "Add Payee"
  | "Statements";

export class NavBar {
  private readonly page: Page;
  readonly tiles: Locator;

  constructor(page: Page) {
    this.page = page;
    // Verified: 12 tiles, all <p class="card-text"> - not links.
    this.tiles = page.locator("p.card-text");
  }

  /**
   * One entry point for every tab. \`switch\` reads as a table of destinations,
   * which is exactly what it is - and adding a tab is one new case, not a new
   * method plus a new test.
   */
  async clickOnTab(tab: TabName): Promise<void> {
    switch (tab) {
      case "Transaction History":
        await this.page.getByText(tab, { exact: true }).click();
        await this.page.waitForURL(/accountDashboard/);
        break;

      case "Pay Bills":
        await this.page.getByText(tab, { exact: true }).click();
        await this.page.waitForURL(/paymentDashboard/);
        break;

      case "Add Payee":
        await this.page.getByText(tab, { exact: true }).click();
        await this.page.waitForURL(/transferDashboard/);
        break;

      case "Statements":
        // "Statements" appears TWICE on this dashboard, so a bare click is a
        // strict-mode violation - see week5/day5_2. Scoping to the first card is a
        // decision, and the component is the right place to make it once.
        await this.page.locator(".card").first().getByText(tab, { exact: true }).click();
        break;

      default:
        // Unreachable while TabName is respected. It catches the caller who reaches
        // this code from untyped JavaScript, where the union type buys nothing.
        throw new Error(\`NavBar: unknown tab "\${tab as string}"\`);
    }
  }
}
`);

// Why a union type beats a string, priced in the only currency that matters: how
// long it takes to find out you were wrong.
const stages = [
  { approach: 'clickOnTab(tab: string)', findsOut: "test run", seconds: 30 },
  { approach: 'clickOnTab(tab: TabName)', findsOut: "typing it", seconds: 0 },
];

for (const s of stages) {
  console.log(`${s.approach.padEnd(28)} you learn at: ${s.findsOut.padEnd(10)} (~${s.seconds}s)`);
}

## When a switch is the wrong tool

`switch` suits a **fixed, small** list. Past roughly a dozen branches, or when the tabs come from
data rather than from you, a lookup object is better:

```ts
private readonly routes: Record<TabName, RegExp> = {
  "Pay Bills": /paymentDashboard/,
  "Add Payee": /transferDashboard/,
};

async clickOnTab(tab: TabName): Promise<void> {
  await this.page.getByText(tab, { exact: true }).click();
  await this.page.waitForURL(this.routes[tab]);
}
```

| | `switch` | lookup object |
|---|---|---|
| Per-tab special handling | **easy** - each case is its own code | awkward |
| 30 tabs | 120 lines | 30 lines |
| Adding one | a `case` | a line of data |

`NavBar` uses `switch` because `"Statements"` genuinely needs different handling from the others.
Uniform tabs belong in the lookup.
